<?php require_once __DIR__.'/../config/database.php';header('Content-Type: application/json');$where=[];$args=[];foreach(['market_cap','pe','revenue_growth','roic','debt_ebitda'] as $k){if(isset($_GET[$k])&&is_numeric($_GET[$k])){$op=in_array($k,['pe','debt_ebitda'],true)?'<=':'>=';$where[]="v.$k $op ?";$args[]=(float)$_GET[$k];}}$sql='SELECT s.ticker,s.company_name,v.market_cap,v.pe,v.revenue_growth,v.roic,v.debt_ebitda FROM stocks s JOIN valuation v ON v.stock_id=s.id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY s.ticker LIMIT 250';$st=db()->prepare($sql);$st->execute($args);echo json_encode(['results'=>$st->fetchAll()]);